import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const phase=process.argv[2],env=process.argv[3],refs={PROD:'YOUR_PROJECT_REF',DEV:'YOUR_PROJECT_REF'},ledgers={PROD:453,DEV:431};
if(!refs[env]||!['prepare','dry-run','apply'].includes(phase))throw Error('Explicit phase and target required');
const pr='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925',base=pr+'/FVI-OPAQUE-AI-'+env+'-RELEASE-20261004-v1',version='20261004081000';
const sha=x=>createHash('sha256').update(x).digest('hex'),q=x=>"'"+x.replaceAll("'","''")+"'";
const vault=await readFile('./.private/CREDENTIALS.md','utf8');const a=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),b=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||b<=a)throw Error('FVI vault boundary absent');
const token=vault.slice(a,b).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_/.test(token??''))throw Error('Management unavailable');
async function query(sql,readOnly){const r=await fetch(`https://api.supabase.com/v1/projects/${refs[env]}/database/query`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:readOnly}),signal:AbortSignal.timeout(110000)});const raw=await r.text();if(!r.ok){const p=base+'-'+phase+'-ERROR-'+Date.now()+'.json';await writeFile(p,JSON.stringify({at:new Date().toISOString(),http:r.status,raw},null,2),{flag:'wx'});throw Error('HTTP'+r.status+'; private diagnostic '+p);}return {raw,rows:JSON.parse(raw)};}
const identity="SELECT current_setting('server_version_num') AS engine,(SELECT count(*) FROM supabase_migrations.schema_migrations)::int AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest";
if(phase==='prepare'){
 const files=[
  [pr+'/FVI-OPAQUE-AI-CURRENT-453-431-20261004.sql','7a65c6aa5bcea398ccf247432fab98dedb14e1a54477ec13ba5ec3aa439679d5'],
  ['docs/handover/returns/2026-10-03-heisenberg-ai-current-guard.sql','69e8666e1c6dc14493405afb079dbfe01185469d98312917a65d833547719dcb'],
  ['docs/handover/returns/2026-10-03-heisenberg-ai.forward.sql','92964eb9943d327fad486219bff07b90b34001171a67973f7965f9f5949c7033'],
  ['docs/handover/returns/2026-10-03-heisenberg-ai-reservation-port.inc.sql','e4ec8f55129bf06ef7fed11c23889b0ca6070f17182602545e5212ed530018bc']
 ];
 const parts=[];for(const [p,h] of files){const s=await readFile(p,'utf8');if(sha(s)!==h)throw Error('Frozen source changed '+p);parts.push(s);}
 const opaque=parts[0].replace(/^BEGIN;\s*$/m,'').replace(/^COMMIT;\s*$/m,'');const split=opaque.indexOf('END $catalog_guard$;')+'END $catalog_guard$;'.length;if(split<20)throw Error('Exact opaque guard missing');
 const current=await query(identity,true);if(current.rows[0]?.ledger!==ledgers[env]||current.rows[0]?.latest!=='20261004080000'||current.rows[0]?.engine!=='170006')throw Error('Current target drift');
 const names=[...new Set(parts.flatMap(s=>[...s.matchAll(/public\.([a-z_][a-z0-9_]*)/g)].map(x=>x[1])))];
 const contracts=await query("SELECT p.oid::text,p.proowner::text,p.proacl::text,p.proconfig,p.prosecdef,p.proargnames,p.proargtypes::text,pg_get_function_result(p.oid) AS result,n.nspname AS schema,p.proname AS name FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='public' AND p.proname IN ('reserve_copilot_dispatch','settle_copilot_dispatch')) OR (n.nspname='private' AND p.proname='fence_copilot_usage')",true);if(contracts.rows.length!==3)throw Error('Exact three existing accounting contracts required');
 let sql="BEGIN; SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='90s';\n"+opaque.slice(0,split)+'\n'+parts[1]+'\n';
 sql+=`LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;\nDO $ledger$ BEGIN IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>${ledgers[env]} OR (SELECT max(version::text) FROM supabase_migrations.schema_migrations)<>'20261004080000' OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version=${q(version)}) THEN RAISE EXCEPTION 'opaque AI ledger/collision drift';END IF;END $ledger$;\n`;
 sql+="CREATE TEMP TABLE _oa_oldledger AS SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(m) ORDER BY version)::text,'UTF8')),'hex') AS sha FROM supabase_migrations.schema_migrations m;\nCREATE TEMP TABLE _oa_oldrows(schema_name text,table_name text,projection text,row_count bigint,sha text);\n";
 sql+=`DO $snapshot$ DECLARE r record;cols text;n bigint;v text;BEGIN FOR r IN SELECT c.oid,n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND c.relname=ANY(ARRAY[${names.map(q).join(',')}]) ORDER BY c.relname LOOP SELECT string_agg(quote_ident(a.attname),',' ORDER BY a.attnum) INTO cols FROM pg_attribute a WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped;EXECUTE format('LOCK TABLE %I.%I IN SHARE MODE',r.nspname,r.relname);EXECUTE format('SELECT count(*),encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]''::jsonb)::text,''UTF8'')),''hex'') FROM (SELECT %s FROM %I.%I)x',cols,r.nspname,r.relname) INTO n,v;INSERT INTO _oa_oldrows VALUES(r.nspname,r.relname,cols,n,v);END LOOP;END $snapshot$;\n`;
 sql+=`CREATE TEMP TABLE _oa_oldfunctions AS SELECT p.oid,p.proowner,p.proacl,p.proconfig,p.prosecdef,p.proargnames,p.proargtypes,pg_get_function_result(p.oid) AS result FROM pg_proc p WHERE p.oid=ANY(ARRAY[${contracts.rows.map(x=>x.oid+'::oid').join(',')}]);\n`;
 const source=opaque.slice(split)+'\n'+parts[2]+'\n'+parts[3];sql+=source+'\n';
 sql+="DO $preserve$ DECLARE r record;n bigint;v text;BEGIN FOR r IN SELECT * FROM _oa_oldrows LOOP EXECUTE format('SELECT count(*),encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]''::jsonb)::text,''UTF8'')),''hex'') FROM (SELECT %s FROM %I.%I)x',r.projection,r.schema_name,r.table_name) INTO n,v;IF n IS DISTINCT FROM r.row_count OR v IS DISTINCT FROM r.sha THEN RAISE EXCEPTION 'opaque AI changed existing rows';END IF;END LOOP;IF EXISTS(SELECT 1 FROM _oa_oldfunctions o LEFT JOIN pg_proc p ON p.oid=o.oid WHERE p.oid IS NULL OR ROW(p.proowner,p.proacl,p.proconfig,p.prosecdef,p.proargnames,p.proargtypes,pg_get_function_result(p.oid)) IS DISTINCT FROM ROW(o.proowner,o.proacl,o.proconfig,o.prosecdef,o.proargnames,o.proargtypes,o.result)) THEN RAISE EXCEPTION 'opaque AI changed existing accounting authority/ABI/config';END IF;END $preserve$;\n";
 sql+=`INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES(${q(version)},'qualified_opaque_api_ai_accounting',ARRAY[${q(parts.join('\n'))}]::text[]);\nDO $post$ BEGIN IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>${ledgers[env]+1} OR (SELECT max(version::text) FROM supabase_migrations.schema_migrations)<>${q(version)} OR (SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(m) ORDER BY version)::text,'UTF8')),'hex') FROM supabase_migrations.schema_migrations m WHERE version<>${q(version)}) IS DISTINCT FROM (SELECT sha FROM _oa_oldledger) THEN RAISE EXCEPTION 'opaque AI old ledger changed';END IF;END $post$;SELECT true AS opaque_ai_checks_passed,(SELECT count(*) FROM _oa_oldrows)::int AS old_tables_preserved;\n`;
 const prepared={at:new Date().toISOString(),environment:env,version,initialLedger:ledgers[env],expectedLedger:ledgers[env]+1,sourceFiles:files,sourceSha256:sha(parts.join('\n')),dryRunSha256:sha(sql+'ROLLBACK;\n'),applySha256:sha(sql+"NOTIFY pgrst,'reload schema';COMMIT;\n")};
 await writeFile(base+'-DRY-RUN.sql',sql+'ROLLBACK;\n',{flag:'wx'});await writeFile(base+'-APPLY.sql',sql+"NOTIFY pgrst,'reload schema';COMMIT;\n",{flag:'wx'});await writeFile(base+'-PREPARED.json',JSON.stringify(prepared,null,2),{flag:'wx'});console.log(JSON.stringify({environment:env,prepared:base+'-PREPARED.json',sourceSha256:prepared.sourceSha256}));
}else{
 const p=JSON.parse(await readFile(base+'-PREPARED.json','utf8')),sql=await readFile(base+(phase==='dry-run'?'-DRY-RUN.sql':'-APPLY.sql'),'utf8');if(sha(sql)!==(phase==='dry-run'?p.dryRunSha256:p.applySha256))throw Error('Immutable packet drift');
 if(phase==='apply'){const d=JSON.parse(await readFile(base+'-DRY-RUN-RECEIPT.json','utf8'));if(!d.rollbackVerified||d.packetSha256!==p.dryRunSha256)throw Error('Exact rollback absent');try{await readFile(base+'-APPLY-RECEIPT.json');throw Error('Already committed; readback only');}catch(e){if(e.code!=='ENOENT')throw e;}}
 const before=await query(identity,true);if(before.rows[0]?.ledger!==ledgers[env]||before.rows[0]?.latest!=='20261004080000')throw Error('Mutable current identity changed');const execution=await query(sql,false),after=await query(identity,true);const ok=execution.rows.some(x=>x.opaque_ai_checks_passed===true)&&(phase==='dry-run'?before.raw===after.raw:after.rows[0]?.ledger===p.expectedLedger&&after.rows[0]?.latest===version);
 await writeFile(base+(phase==='dry-run'?'-DRY-RUN-RECEIPT.json':'-APPLY-RECEIPT.json'),JSON.stringify({at:new Date().toISOString(),environment:env,phase,packetSha256:sha(sql),before,execution,after,rollbackVerified:phase==='dry-run'&&ok,commitVerified:phase==='apply'&&ok,hostedInferenceAcceptance:false},null,2),{flag:'wx'});if(!ok)throw Error('Exact postconditions not proven');console.log(JSON.stringify({environment:env,phase,verified:ok,ledger:after.rows[0].ledger,latest:after.rows[0].latest}));
}
